import { test, expect } from '@playwright/test';

test.describe('Edit Task Functionality', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('http://localhost:3000');

    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should display Edit button for existing task', async ({ page }) => {
    // Verify that a task exists and has an Edit button
    const editButton = page.getByRole('button', { name: /edit/i }).first();

    // Check that the Edit button is visible
    await expect(editButton).toBeVisible();
  });

  test('should open edit form when Edit button is clicked', async ({ page }) => {
    // Click the Edit button for the first task
    const editButton = page.getByRole('button', { name: /edit/i }).first();
    await editButton.click();

    // Verify that the edit form or modal appears
    const editForm = page.getByRole('heading', { name: /edit task/i });
    await expect(editForm).toBeVisible();
  });

  test('should update task title when edited and saved', async ({ page }) => {
    // Click the Edit button
    const editButton = page.getByRole('button', { name: /edit/i }).first();
    await editButton.click();

    // Wait for the edit form to appear
    const titleInput = page.getByLabel(/task title/i);
    await expect(titleInput).toBeVisible();

    // Clear the current title and enter a new one
    await titleInput.clear();
    await titleInput.fill('Updated Task Title');

    // Click the Save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify the task has been updated
    const updatedTask = page.getByText('Updated Task Title');
    await expect(updatedTask).toBeVisible();
  });

  test('should allow editing task description', async ({ page }) => {
    // Click the Edit button
    const editButton = page.getByRole('button', { name: /edit/i }).first();
    await editButton.click();

    // Find and fill the description field
    const descriptionInput = page.getByLabel(/task description/i);
    await expect(descriptionInput).toBeVisible();

    // Update the description
    await descriptionInput.clear();
    await descriptionInput.fill('This is an updated task description');

    // Save the changes
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify the description has been updated
    const updatedDescription = page.getByText('This is an updated task description');
    await expect(updatedDescription).toBeVisible();
  });

  test('should close edit form when Cancel button is clicked', async ({ page }) => {
    // Click the Edit button
    const editButton = page.getByRole('button', { name: /edit/i }).first();
    await editButton.click();

    // Verify the edit form is visible
    const editForm = page.getByRole('heading', { name: /edit task/i });
    await expect(editForm).toBeVisible();

    // Click the Cancel button
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await cancelButton.click();

    // Verify the edit form is closed
    await expect(editForm).not.toBeVisible();
  });
});
